class Dual:
    def __init__(self, v, d=0.0):
        self.v = v
        self.d = d

    def _w(self, o):
        return o if isinstance(o, Dual) else Dual(o, 0.0)

    def __add__(self, o):
        o = self._w(o)
        return Dual(self.v + o.v, self.d + o.d)

    __radd__ = __add__

    def __sub__(self, o):
        o = self._w(o)
        return Dual(self.v - o.v, self.d - o.d)

    def __rsub__(self, o):
        return self._w(o) - self

    def __mul__(self, o):
        o = self._w(o)
        return Dual(self.v * o.v, self.d * o.v + self.v * o.d)

    __rmul__ = __mul__

    def __truediv__(self, o):
        o = self._w(o)
        return Dual(self.v / o.v, (self.d * o.v - self.v * o.d) / o.v ** 2)

    def __rtruediv__(self, o):
        return self._w(o) / self

    def __pow__(self, n):
        return Dual(self.v ** n, n * self.v ** (n - 1) * self.d)

def turunan_dual(f, x):
    r = f(Dual(x, 1.0))
    if isinstance(r, Dual):
        return round(float(r.d), 4) + 0.0
    return 0.0

